import JSZip from 'jszip';
import { ApkArtifact, Project } from '../types/ide';

const GRADLEW_UNIX_SCRIPT = `#!/bin/sh
#
# Gradle start up script for UN*X — Generated by CodeStudio Mobile
#
APP_BASE_NAME=\`basename "$0"\`
APP_HOME="\`pwd -P\`"
DEFAULT_JVM_OPTS='"-Xmx2048m" "-Xms512m"'
CLASSPATH=$APP_HOME/gradle/wrapper/gradle-wrapper.jar
exec java $DEFAULT_JVM_OPTS -classpath "$CLASSPATH" org.gradle.wrapper.GradleWrapperMain "$@"
`;

const GRADLEW_BAT_SCRIPT = `@rem Gradle startup script for Windows — Generated by CodeStudio Mobile
@if "%DEBUG%" == "" @echo off
set DIRNAME=%~dp0
if "%DIRNAME%" == "" set DIRNAME=.
set APP_BASE_NAME=%~n0
set APP_HOME=%DIRNAME%
set DEFAULT_JVM_OPTS="-Xmx2048m" "-Xms512m"
set CLASSPATH=%APP_HOME%\\gradle\\wrapper\\gradle-wrapper.jar
java %DEFAULT_JVM_OPTS% -classpath "%CLASSPATH%" org.gradle.wrapper.GradleWrapperMain %*
`;

const GRADLE_WRAPPER_PROPERTIES = `distributionBase=GRADLE_USER_HOME
distributionPath=wrapper/dists
distributionUrl=https\\://services.gradle.org/distributions/gradle-8.7-all.zip
networkTimeout=10000
validateDistributionUrl=true
zipStoreBase=GRADLE_USER_HOME
zipStorePath=wrapper/dists
`;

const PROGUARD_RULES = `# Add project specific ProGuard rules here.
-keepattributes *Annotation*
-keepclassmembers class * {
    @android.webkit.JavascriptInterface <methods>;
}
-keep class **.R$* { *; }
`;

export function getProjectEstimatedSizeMb(project: Project): string {
  const fileCount = project.files.filter((f) => f.type === 'file').length;
  const baseMb =
    project.language === 'Flutter'
      ? 28.4
      : project.language === 'React'
      ? 24.6
      : project.language === 'Kotlin'
      ? 24.8
      : 23.5;
  return (baseMb + fileCount * 0.12).toFixed(1);
}

